const raw = $input.first().json;

// n8n v2 webhook aninha o body em .body, v1 coloca direto
const ip = (raw.body && raw.body.ip) ? raw.body.ip : raw.ip;

if (!ip || typeof ip !== 'string') {
  throw new Error('IP address is required. Received: ' + JSON.stringify(raw));
}

const ipTrim = ip.trim();
const ipRegex = /^(\d{1,3}\.){3}\d{1,3}$/;

if (!ipRegex.test(ipTrim)) {
  throw new Error('Invalid IP address format: ' + ipTrim);
}

const reversed = ipTrim.split('.').reverse().join('.');
return [{ json: { ip: ipTrim, reversed_ip: reversed + '.in-addr.arpa' } }];

const input = $input.first();
if (input.json.error) {
  return [{ json: { vt: null, vt_error: input.json.error } }];
}
return [{ json: { vt: input.json } }];

const input = $input.first();
if (input.json.error) {
  return [{ json: { abuse: null, abuse_error: input.json.error } }];
}
return [{ json: { abuse: input.json } }];

const input = $input.first();
if (input.json.error) {
  return [{ json: { ipinfo: null, ipinfo_error: input.json.error } }];
}
return [{ json: { ipinfo: input.json } }];

const input = $input.first();
if (input.json.error) {
  return [{ json: { dns: null, dns_error: input.json.error } }];
}
return [{ json: { dns: input.json } }];

const d = $input.first().json;

// ─── Original IP (fallback chain) ───────────────────────────
const ip = d.ipinfo?.ip || $('Prepare IP').first().json.ip || 'Unknown';

// ─── IPInfo ─────────────────────────────────────────────────
const country  = d.ipinfo?.country  || 'Unknown';
const region   = d.ipinfo?.region   || 'Unknown';
const city     = d.ipinfo?.city     || 'Unknown';
const postal   = d.ipinfo?.postal   || 'Unknown';
const timezone = d.ipinfo?.timezone || 'Unknown';
const hostname = d.ipinfo?.hostname || null;
const orgRaw   = d.ipinfo?.org      || '';
const loc      = d.ipinfo?.loc      ? d.ipinfo.loc.split(',') : [null, null];
const lat      = loc[0] ? parseFloat(loc[0]) : null;
const lon      = loc[1] ? parseFloat(loc[1]) : null;

const asnMatch = orgRaw.match(/^(AS\d+)\s+(.+)/);
const asn      = asnMatch ? asnMatch[1] : 'Unknown';
const orgName  = asnMatch ? asnMatch[2] : (orgRaw || 'Unknown');

// ─── VirusTotal ──────────────────────────────────────────────
let vtMalicious    = 0;
let vtSuspicious   = 0;
let vtHarmless     = 0;
let vtUndetected   = 0;
let vtCommunity    = null;
let vtReputation   = null;
let vtCountry      = null;
let vtASN          = null;
let vtASOwner      = null;
let vtLastAnalysis = null;

if (d.vt?.data?.attributes) {
  const attrs = d.vt.data.attributes;
  const stats = attrs.last_analysis_stats || {};
  vtMalicious    = stats.malicious    || 0;
  vtSuspicious   = stats.suspicious   || 0;
  vtHarmless     = stats.harmless     || 0;
  vtUndetected   = stats.undetected   || 0;
  vtReputation   = attrs.reputation   ?? null;
  vtCommunity    = attrs.total_votes  ? attrs.total_votes.malicious + '/' + (attrs.total_votes.malicious + attrs.total_votes.harmless) + ' community votes malicious' : null;
  vtCountry      = attrs.country      || null;
  vtASN          = attrs.asn          || null;
  vtASOwner      = attrs.as_owner     || null;
  vtLastAnalysis = attrs.last_analysis_date ? new Date(attrs.last_analysis_date * 1000).toISOString() : null;
}

// ─── AbuseIPDB ───────────────────────────────────────────────
let abuseScore   = 0;
let abuseReports = 0;
let abuseUsageType = null;
let abuseDomain    = null;
let abuseISP       = null;
let abuseCountry   = null;
let abuseWhitelisted = false;
let abuseLastReport = null;

if (d.abuse?.data) {
  const a = d.abuse.data;
  abuseScore       = a.abuseConfidenceScore ?? 0;
  abuseReports     = a.totalReports         ?? 0;
  abuseUsageType   = a.usageType            || null;
  abuseDomain      = a.domain               || null;
  abuseISP         = a.isp                  || null;
  abuseCountry     = a.countryCode          || null;
  abuseWhitelisted = a.isWhitelisted         ?? false;
  abuseLastReport  = a.lastReportedAt       || null;
}

// ─── Reverse DNS ─────────────────────────────────────────────
let reverseDns = hostname || null;
if (!reverseDns && d.dns?.Answer && d.dns.Answer.length > 0) {
  reverseDns = d.dns.Answer[0].data.replace(/\.$/, '');
}

// ─── Risk score (simple heuristic) ──────────────────────────
let riskScore = 0;
if (vtMalicious > 0)  riskScore += vtMalicious * 20;
if (vtSuspicious > 0) riskScore += vtSuspicious * 10;
if (abuseScore  > 0)  riskScore += abuseScore;
riskScore = Math.min(riskScore, 100);

let riskLevel = 'Low';
if (riskScore >= 70) riskLevel = 'High';
else if (riskScore >= 30) riskLevel = 'Medium';

// ─── Final payload ───────────────────────────────────────────
return [{ json: {
  ip,
  country,
  region,
  city,
  postal,
  timezone,
  asn,
  org: orgName,
  reverse_dns: reverseDns || 'N/A',
  location: { lat, lon },
  risk: {
    score: riskScore,
    level: riskLevel
  },
  reputation: {
    virustotal: {
      malicious:     vtMalicious,
      suspicious:    vtSuspicious,
      harmless:      vtHarmless,
      undetected:    vtUndetected,
      reputation:    vtReputation,
      community:     vtCommunity,
      last_analysis: vtLastAnalysis,
      country:       vtCountry,
      asn:           vtASN,
      as_owner:      vtASOwner
    },
    abuseipdb: {
      abuseConfidenceScore: abuseScore,
      totalReports:         abuseReports,
      usageType:            abuseUsageType,
      domain:               abuseDomain,
      isp:                  abuseISP,
      countryCode:          abuseCountry,
      isWhitelisted:        abuseWhitelisted,
      lastReportedAt:       abuseLastReport
    }
  },
  network: {
    isp:      abuseISP || orgName,
    domain:   abuseDomain || hostname || 'N/A',
    asn,
    org:      orgName
  },
  sources: {
    virustotal: !d.vt_error,
    abuseipdb:  !d.abuse_error,
    ipinfo:     !d.ipinfo_error,
    dns:        !d.dns_error
  }
}}];
